static controller_component_2_event controller_Component_2_get_next_event(Controller_Component_2* handle)
{
	controller_component_2_event next_event;
	controller_component_2_event_init(&next_event, Controller_Component_2_invalid_event);
	if(controller_component_2_eventqueue_size(&(handle->in_event_queue)) > 0) {
		next_event = controller_component_2_eventqueue_pop(&(handle->in_event_queue));
	}
	return next_event;
}

static sc_boolean controller_Component_2_dispatch_next_event(Controller_Component_2* handle)
{
	controller_component_2_event nextEvent;
	nextEvent = controller_Component_2_get_next_event(handle);
	return controller_Component_2_dispatch_event(handle, &nextEvent);
}
